-- ---------------------------------------------------------------------------
-- Payment-due LMS access control (services/class-access-service.ts): two
-- class-level settings.
--
-- ADDITIVE ONLY: two NOT NULL columns with constant defaults on "Class"
-- (existing classes: restriction OFF, 5 grace days, so their behaviour is
-- unchanged) and one CHECK. No existing row or column is changed.
-- Generated by `prisma migrate diff` from schema.prisma; the CHECK and the
-- lock timeout are hand-written.
--
-- Deploy order: after 20261120120000_add_class_student_fee_free_card and
-- BEFORE the code that reads these columns.
-- Guarded by tests/class-access/class-access-migration-guard.test.cjs.
-- ---------------------------------------------------------------------------

-- MANUAL: fail instead of waiting indefinitely for a lock on "Class".
-- Session-level SET (not SET LOCAL): it works whether Prisma runs this script
-- as one implicit transaction or statement by statement. RESET at the end
-- restores the default. See docs/lecture-attendance.md ("Lock timeout").
SET lock_timeout = '5s';

-- AlterTable
ALTER TABLE "Class" ADD COLUMN     "paymentGracePeriodDays" INTEGER NOT NULL DEFAULT 5,
ADD COLUMN     "restrictUnpaidStudentAccess" BOOLEAN NOT NULL DEFAULT false;

-- Hand-written: the grace period the settings UI and API accept.
ALTER TABLE "Class" ADD CONSTRAINT "Class_paymentGracePeriodDays_check"
  CHECK ("paymentGracePeriodDays" BETWEEN 0 AND 30);

-- MANUAL: restore the default lock timeout for the rest of the session.
RESET lock_timeout;
